cypress_script:
describe('Editable Web Table CRUD Operations', () => {
  it('should add a new record successfully', () => {
    cy.visit('https://demoqa.com/webtables');
    cy.get('#addNewRecordButton').click();
    // Assume the modal for adding a record appears here
    // Assuming there are inputs for first name, last name, age, email, and salary
    cy.get('input[placeholder="Type to search"]').type('John');
    cy.url().should('include', '/webtables');
  });

  it('should not allow adding a record with empty fields', () => {
    cy.visit('https://demoqa.com/webtables');
    cy.get('#addNewRecordButton').click();
    // Submitting the form without filling it should not change the URL
    cy.get('button[type="button"]').first().click(); // Assuming this is the submit
    cy.url().should('include', '/webtables');
    cy.get('#searchBox').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Editable Web Table CRUD Operations', () => {
  test('should add a new record successfully', async ({ page }) => {
    await page.goto('https://demoqa.com/webtables');
    await page.click('#addNewRecordButton');
    await page.fill('input[placeholder="Type to search"]', 'John');
    await expect(page).toHaveURL(/webtables/);
  });

  test('should not allow adding a record with empty fields', async ({ page }) => {
    await page.goto('https://demoqa.com/webtables');
    await page.click('#addNewRecordButton');
    await page.click('button[type="button"]').first(); // Assuming this is the submit
    await expect(page).toHaveURL(/webtables/);
    await expect(page.locator('#searchBox')).toBeVisible();
  });
});
